-- Additive only: no inferred organization/history context and no historical score rewrite.
CREATE TABLE org_schools(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),revision INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE org_classes(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES org_schools(id),name TEXT NOT NULL,academic_year TEXT NOT NULL CHECK(academic_year ~ '^\d{4}-\d{4}$'),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),revision INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(school_id,academic_year,name));
ALTER TABLE auth_users ADD COLUMN revision INT NOT NULL DEFAULT 0,ADD COLUMN credential_version INT NOT NULL DEFAULT 0,ADD COLUMN school_id TEXT REFERENCES org_schools(id),ADD COLUMN class_id TEXT REFERENCES org_classes(id),ADD COLUMN profile_bio TEXT NOT NULL DEFAULT '',ADD COLUMN avatar_key TEXT NOT NULL DEFAULT 'mascot',ADD COLUMN email_verified_at TIMESTAMPTZ,ADD COLUMN disabled_from_status TEXT,ADD COLUMN disabled_at TIMESTAMPTZ,ADD COLUMN activation_pending BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE org_assignments(id UUID PRIMARY KEY,user_id TEXT NOT NULL REFERENCES auth_users(id),school_id TEXT NOT NULL REFERENCES org_schools(id),class_id TEXT REFERENCES org_classes(id),homeroom BOOLEAN NOT NULL DEFAULT FALSE,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),ended_at TIMESTAMPTZ);
CREATE UNIQUE INDEX org_assignment_current_user ON org_assignments(user_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX org_assignment_current_homeroom ON org_assignments(class_id) WHERE ended_at IS NULL AND homeroom;
ALTER TABLE survey_campaigns ADD COLUMN school_id TEXT REFERENCES org_schools(id);
ALTER TABLE class_join_codes ADD COLUMN school_id TEXT REFERENCES org_schools(id),ADD COLUMN class_id TEXT REFERENCES org_classes(id);
ALTER TABLE test_attempts ADD COLUMN context_status TEXT NOT NULL DEFAULT 'legacy_unknown' CHECK(context_status IN ('snapshot','legacy_unknown')),ADD COLUMN context_school_id TEXT REFERENCES org_schools(id),ADD COLUMN context_class_id TEXT REFERENCES org_classes(id),ADD COLUMN context_snapshot JSONB;
ALTER TABLE test_templates ADD COLUMN duration_minutes INT CHECK(duration_minutes BETWEEN 1 AND 240),ADD COLUMN icon_key TEXT NOT NULL DEFAULT 'Zap',ADD COLUMN color_key TEXT NOT NULL DEFAULT 'primary';
CREATE TABLE account_challenges(id UUID PRIMARY KEY,user_id TEXT REFERENCES auth_users(id),purpose TEXT NOT NULL CHECK(purpose IN ('reset','invite','email','verify-email','reauth')),session_jti TEXT,otp_hash TEXT NOT NULL,second_hash TEXT,attempts_left INT NOT NULL DEFAULT 5 CHECK(attempts_left>=0),state JSONB NOT NULL DEFAULT '{}',expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE account_reauth(id UUID PRIMARY KEY,user_id TEXT NOT NULL REFERENCES auth_users(id),session_jti TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,consumed_at TIMESTAMPTZ);
CREATE TABLE account_email_outbox(id UUID PRIMARY KEY,challenge_id UUID REFERENCES account_challenges(id),payload JSONB,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','sent','failed')),attempts INT NOT NULL DEFAULT 0,next_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),lease_id UUID,lease_until TIMESTAMPTZ,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX account_mail_pending ON account_email_outbox(next_at) WHERE status IN ('pending','processing');
CREATE TABLE account_audit(id UUID PRIMARY KEY,actor_id TEXT REFERENCES auth_users(id),target_id TEXT NOT NULL,action TEXT NOT NULL,fields TEXT[] NOT NULL DEFAULT '{}',request_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE account_receipts(actor_id TEXT NOT NULL,request_id UUID NOT NULL,action TEXT NOT NULL,digest TEXT NOT NULL,response JSONB NOT NULL,expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW()+INTERVAL '24 hours',PRIMARY KEY(actor_id,request_id));
